  'The syllabus provides a comprehensive core for inventory and warehouse management. This includes demand inputs, slotting, inbound/outbound process control, safety, labor, WMS/ERP integration, automation, analytics, resilience, sustainability, and a capstone improvement plan.',
  $iwmjson${"slug": "inventory-and-warehouse-management", "title": "Inventory and Warehouse Management", "description": "The syllabus provides a comprehensive core for inventory and warehouse management. This includes demand inputs, slotting, inbound/outbound process control, safety, labor, WMS/ERP integration, automation, analytics, resilience, sustainability, and a capstone improvement plan.", "topics": [{"id": "f194d7a2-5097-4621-b818-d738a5c4318b", "type": "topic", "title": "Inventory and Warehouse Strategy in Supply Chains", "description": "Frame inventory and warehousing as strategic levers for service, cost, resilience, and working capital.", "children": [{"id": "edc52696-6f0a-4cf7-84e3-a880c8dbf0a2", "type": "subtopic", "title": "Strategic role of inventory", "children": [{"id": "3823f478-8129-4288-a5d5-2ed0c41cae96", "type": "concept", "title": "Inventory as buffer, decoupling point, and service promise"}, {"id": "5e2e72d2-28ff-4f31-a806-a1104fab3e68", "type": "concept", "title": "Cost-service-resilience tradeoffs"}, {"id": "e353c4cb-2c57-41a9-934c-6f450c077565", "type": "concept", "title": "Make-to-stock, make-to-order, assemble-to-order, and engineer-to-order contexts"}, {"id": "0ec34208-45e6-464c-87f3-e1528883fc7d", "type": "concept", "title": "Inventory ownership and working-capital implications"}], "description": "Inventory is not just a stockroom problem; it shapes service levels, working capital, resilience, and customer experience."}, {"id": "30358822-32ed-4a0f-b346-69b34e8d1fef", "type": "subtopic", "title": "Warehouse role and network fit", "children": [{"id": "c6e90be6-867c-46de-aa70-d4a4419aedba", "type": "concept", "title": "Distribution centers, fulfillment centers, cross-docks, forward stocking locations, and returns centers"}, {"id": "4a239c51-c6c7-47b8-be5b-e1f50a024b2d", "type": "concept", "title": "Centralized versus decentralized inventory"}, {"id": "34927d93-ceb7-4bd9-8063-9fee9a564b6d", "type": "concept", "title": "Inbound, outbound, and reverse flow roles"}, {"id": "a8723a45-21ae-4476-9076-980fad40cf9a", "type": "concept", "title": "Customer promise, lead time, and geographic coverage"}], "description": "Students learn why warehouses exist and how their role changes across distribution networks."}, {"id": "906f39c5-f404-4f39-bf8b-0efa31004101", "type": "subtopic", "title": "Operating model choices", "children": [{"id": "05ab356f-dcef-44d1-a6a9-7e11b0abc68c", "type": "concept", "title": "Service-level targets"}, {"id": "96ed4778-348a-4e8e-9bbe-f7c88dd41490", "type": "concept", "title": "Process standardization"}, {"id": "cb72751b-57d7-4e75-98d3-0ac14944b56c", "type": "concept", "title": "Automation readiness"}, {"id": "df0c849c-7ed8-4200-abf7-3b68f7da7209", "type": "concept", "title": "Governance and continuous improvement"}], "description": "This subtopic connects policy, process, technology, and labor into one operating system."}]}, {"id": "3fd8d715-cad1-49fa-9a65-42ad74d526d8", "type": "topic", "title": "Inventory Costs, Tradeoffs, and Financial Impact", "description": "Analyze carrying, ordering, shortage, obsolescence, and working-capital costs.", "children": [{"id": "3a205423-28ab-4384-ba08-0c4edebdfb06", "type": "subtopic", "title": "Inventory cost categories", "children": [{"id": "1bffe2c0-5af8-4a07-b290-7ce96d718e96", "type": "concept", "title": "Carrying cost, ordering cost, shortage cost, obsolescence, damage, shrinkage, and handling cost"}, {"id": "2ba82890-1a71-4707-849b-4e7e124c7920", "type": "concept", "title": "Capital cost and opportunity cost"}, {"id": "83fa0ee8-3c6a-45f9-81e2-597bb9b3f588", "type": "concept", "title": "Storage, insurance, taxes, and depreciation"}, {"id": "35805cb9-48b6-4a5c-931c-5e9f6d19a10c", "type": "concept", "title": "Cost-to-serve by item or customer"}], "description": "Students learn to identify the true cost of inventory decisions beyond unit price."}, {"id": "54055882-1943-4c07-b680-4cac349425f5", "type": "subtopic", "title": "Financial statement and cash-flow impact", "children": [{"id": "0cb11b7d-2c8f-4365-a8b1-0d9dcbf5581a", "type": "concept", "title": "Working capital and cash conversion cycle"}, {"id": "5ca852c9-ee98-4c58-88c3-f015317d358c", "type": "concept", "title": "Inventory turns and days inventory outstanding"}, {"id": "7f222f97-b7b6-455b-9575-d4218ec96c51", "type": "concept", "title": "Gross margin and markdown exposure"}, {"id": "33886c17-bb86-4e6a-8fbe-71c21332b6ab", "type": "concept", "title": "Write-offs and reserve implications"}], "description": "Inventory policy affects cash, margins, and risk. This section helps students translate operations choices into business language."}, {"id": "a602bb71-ec64-4926-802c-ca2a365b8db5", "type": "subtopic", "title": "Tradeoff thinking", "children": [{"id": "37f26076-5c40-4b1f-90db-75b0bfd18d6b", "type": "concept", "title": "Service versus cost"}, {"id": "80d0182c-12b4-4a1b-b7e6-16e4b0cadcfa", "type": "concept", "title": "Bulk discounts versus holding cost"}, {"id": "0da8647f-640e-44ef-ae44-b05c76b86559", "type": "concept", "title": "Stockout risk versus obsolescence"}, {"id": "8df6d6bd-da2c-42a0-ae20-b1897a59aea0", "type": "concept", "title": "Local availability versus pooling benefits"}], "description": "Students learn that there is rarely one perfect answer; good managers make explicit tradeoffs."}]}, {"id": "e3db681c-e5d9-4e97-9599-bd53479406af", "type": "topic", "title": "Demand Patterns, Forecasting Inputs, and Replenishment Logic", "description": "Connect demand behavior and forecasts to stocking and replenishment decisions.", "children": [{"id": "42f1d0d7-6959-465b-b42b-e51ceb70360c", "type": "subtopic", "title": "Demand behavior", "children": [{"id": "888cf1a4-8b58-495f-862a-90f08dcfdcbf", "type": "concept", "title": "Trend, seasonality, cycles, and noise"}, {"id": "5f91c0b4-34bd-4670-8778-c707a5670bcf", "type": "concept", "title": "Intermittent and slow-moving items"}, {"id": "5125b658-aac2-4043-91ba-4db627d07861", "type": "concept", "title": "Promotions, launches, and end-of-life effects"}, {"id": "178326f1-d748-4520-9dc8-f2baf7750f14", "type": "concept", "title": "Demand sensing and exception signals"}], "description": "Inventory policies depend on how demand behaves. Students learn to distinguish stable, seasonal, intermittent, promotional, and lumpy demand."}, {"id": "826ba3b7-11ae-49e2-9952-974db38f044c", "type": "subtopic", "title": "Forecasting inputs", "children": [{"id": "cea951e8-14cd-4d36-90c2-2166beb631bd", "type": "concept", "title": "Historical demand, orders, shipments, lost sales, and substitutions"}, {"id": "f915ecd0-3516-40c8-bd14-ea96e56d9a54", "type": "concept", "title": "Lead times, supplier reliability, and minimum order quantities"}, {"id": "0bb65f48-eb20-41bb-850d-96c6814e6e1c", "type": "concept", "title": "Forecast error and bias"}, {"id": "53996d95-9023-4403-9f83-e465608639ca", "type": "concept", "title": "Collaborative inputs from sales, procurement, and operations"}], "description": "This subtopic teaches students what data planners need before calculating inventory targets."}, {"id": "41c085e1-3cf6-4b09-99aa-8198e7e585fb", "type": "subtopic", "title": "Replenishment logic", "children": [{"id": "55c5b825-2e80-4690-92ce-e4ceabd5136a", "type": "concept", "title": "Continuous review versus periodic review"}, {"id": "5371314c-6e5d-45a7-944b-0388b4bd932b", "type": "concept", "title": "Min-max systems"}, {"id": "a06de685-940b-49da-b573-e6375aca361d", "type": "concept", "title": "Order-up-to levels"}, {"id": "725a41ea-3339-4609-86e6-cc4b8b2bf4a8", "type": "concept", "title": "Planning calendars and review frequency"}], "description": "Students learn how forecast, demand history, lead time, and service targets translate into ordering decisions."}]}, {"id": "05177dc0-51d6-452d-bd2f-4a8a7ef4fe98", "type": "topic", "title": "EOQ, Reorder Points, and Lot-Sizing Models", "description": "Use foundational inventory models to set order quantities and replenishment triggers.", "children": [{"id": "cc4578ad-d00c-4487-8852-6a9f5ce1dad3", "type": "subtopic", "title": "Economic order quantity", "children": [{"id": "7ebde30d-fbe4-4ed3-a4e9-ff179f8a81a4", "type": "concept", "title": "EOQ formula logic"}, {"id": "b396fc0c-a8bb-4fbf-9654-110899b83e6f", "type": "concept", "title": "Ordering/setup cost and holding cost"}, {"id": "f596afef-f313-42a3-bdfe-e4a370cd21d0", "type": "concept", "title": "Sensitivity analysis"}, {"id": "817dfb6b-0238-44bc-a514-242bc3a684bd", "type": "concept", "title": "Quantity discounts and practical constraints"}], "description": "EOQ introduces the logic of balancing ordering and holding costs. Students learn the assumptions and limits of the classic model."}, {"id": "0a1699a5-b076-4edd-8380-4723d78ac368", "type": "subtopic", "title": "Reorder points", "children": [{"id": "60ef9e6c-ce76-4f86-b378-34d42365f0ee", "type": "concept", "title": "Lead-time demand"}, {"id": "85d05f91-24cc-4510-95eb-f0fabd865f4a", "type": "concept", "title": "Reorder point formula"}, {"id": "5f507e05-6ade-46c1-a74f-bb41290892d3", "type": "concept", "title": "Demand during lead time"}, {"id": "f67085ee-4754-410b-8dfe-327d52c6e792", "type": "concept", "title": "Supplier lead-time variability"}], "description": "Reorder points decide when to buy or make. This section connects lead-time demand and safety stock to operational triggers."}, {"id": "ee3f7378-0a33-47e6-8b16-04f608d51e9c", "type": "subtopic", "title": "Lot-sizing and replenishment constraints", "children": [{"id": "241bf6fe-4124-492d-9182-ecf28afe13ed", "type": "concept", "title": "Minimum order quantities"}, {"id": "a5b44cfa-342b-43fb-98e2-23a473841cbc", "type": "concept", "title": "Pack, pallet, and container multiples"}, {"id": "d9f545d3-429d-44a4-a2ce-8cb311b2b135", "type": "concept", "title": "Capacity and supplier constraints"}, {"id": "cb30bd10-f276-4258-ac39-c728106bb4d7", "type": "concept", "title": "Joint replenishment and order consolidation"}], "description": "Students learn how real-world constraints modify textbook models."}]}, {"id": "825fe751-3630-4504-a42d-64da54c6c578", "type": "topic", "title": "Safety Stock, Service Levels, and Uncertainty", "description": "Design buffers for demand and lead-time variability while balancing cost and service.", "children": [{"id": "54e0aa8e-c857-46da-93c8-8107d38f86b6", "type": "subtopic", "title": "Uncertainty and buffers", "children": [{"id": "a8aeacbb-299a-4904-a47f-d6bba77eb0a3", "type": "concept", "title": "Demand variability"}, {"id": "eeb62aee-b6fd-4633-8711-907fcf54354f", "type": "concept", "title": "Lead-time variability"}, {"id": "b097f42a-4a7f-4f8a-9849-7b9a9aee99d4", "type": "concept", "title": "Supply disruptions"}, {"id": "8fd6e764-dd06-4677-86cd-15024bdd7b7b", "type": "concept", "title": "Service-critical items"}], "description": "Safety stock protects service when forecasts or lead times are wrong. Students learn what uncertainty is being buffered and why."}, {"id": "37a8eed8-8a63-4b15-b46b-d3262fa87e7e", "type": "subtopic", "title": "Service-level design", "children": [{"id": "92fc12e1-24e1-4fd7-a906-91df293e2dc8", "type": "concept", "title": "Cycle service level"}, {"id": "4c734a2b-a8cc-4c99-8741-d5570ab1c6de", "type": "concept", "title": "Fill rate"}, {"id": "a7ad00cf-80d9-4afa-bdf0-7d54e046ae14", "type": "concept", "title": "Stockout probability"}, {"id": "74378f4e-ae2f-4394-9e9d-1c207b2f06db", "type": "concept", "title": "Criticality-based service targets"}], "description": "This subtopic introduces the difference between service goals and inventory investment."}, {"id": "35591e37-96a2-47fb-9fb7-a92749088b97", "type": "subtopic", "title": "Pooling and risk reduction", "children": [{"id": "40ddb66a-dadc-4d8e-97c2-3dc06ccbf957", "type": "concept", "title": "Inventory pooling"}, {"id": "8a660a4a-4c06-4e1d-b69f-420346c01b8f", "type": "concept", "title": "Postponement"}, {"id": "fec23a0a-ed91-499a-8a44-9fcf33b14232", "type": "concept", "title": "Supplier reliability improvement"}, {"id": "e6fec558-beeb-