"dc6661e9-f3ea-4489-92f8-00122bf377ef", "type": "topic", "title": "Warehouse Labor, Lean Flow, Quality, and Continuous Improvement", "description": "Apply lean, quality, labor planning, and standard work to warehouse performance.", "children": [{"id": "ece83008-7b69-4ba3-a8b6-e54c688921a7", "type": "subtopic", "title": "Labor planning and standards", "children": [{"id": "d89e0e70-6e80-4c71-bf28-33477c2abc6f", "type": "concept", "title": "Engineered labor standards"}, {"id": "0af584e4-68a5-49f2-b0db-81a08db1ebbe", "type": "concept", "title": "Scheduling and cross-training"}, {"id": "6b8f1175-4a88-4d6f-b47f-a7bfbc8ca752", "type": "concept", "title": "Productivity and utilization"}, {"id": "8999320c-7df8-4364-bf15-99cb257bdfbe", "type": "concept", "title": "Fairness, fatigue, and morale"}], "description": "Students learn how to plan labor around workload and process standards."}, {"id": "ea426c60-e3b0-4812-ae06-d2bc242822ba", "type": "subtopic", "title": "Lean warehouse flow", "children": [{"id": "72ad9328-167e-4ff4-86ec-da7d27a160f2", "type": "concept", "title": "5S, visual management, standard work, and kaizen"}, {"id": "58327cd7-c434-4509-a610-8f74631d4622", "type": "concept", "title": "Waste in travel, waiting, motion, defects, and overprocessing"}, {"id": "17df56fc-5dec-4d1d-a9c9-e62fe7f580ae", "type": "concept", "title": "Flow racks and point-of-use storage"}, {"id": "948fc8d2-1bdc-4ff9-809e-111d9ade0061", "type": "concept", "title": "Daily management systems"}], "description": "Lean thinking helps remove waste and stabilize processes."}, {"id": "77f09499-5355-4ec2-aac3-c261a2c37323", "type": "subtopic", "title": "Quality and error reduction", "children": [{"id": "6907fb6a-ae73-4ca6-8f6d-0a4505e508f0", "type": "concept", "title": "Poka-yoke"}, {"id": "aa82bb29-82c0-473d-b437-af777af9d32c", "type": "concept", "title": "Root cause analysis"}, {"id": "8feaaf87-0f36-434a-ae5b-44c6df8f36f0", "type": "concept", "title": "Defect tracking"}, {"id": "30739fae-1997-473b-85c7-9c2373dce315", "type": "concept", "title": "Corrective and preventive action"}], "description": "Students learn to design quality into the process rather than inspect it in at the end."}]}, {"id": "9cb2d802-c48d-4d51-95b8-64b575b68129", "type": "topic", "title": "Inventory Analytics, KPIs, Dashboards, and Simulation", "description": "Measure inventory and warehouse performance with dashboards, models, and scenario analysis.", "children": [{"id": "d009e23a-0159-4409-a01b-cde4123ae202", "type": "subtopic", "title": "Inventory KPIs", "children": [{"id": "980d5231-c991-4b69-aac4-4ecc16b0a544", "type": "concept", "title": "Inventory turns, days of supply, stockout rate, fill rate, excess and obsolete inventory"}, {"id": "f66428d6-37c6-4902-92f2-e0ff4608ca61", "type": "concept", "title": "Forecast error and bias"}, {"id": "55599e02-965a-4ed5-bcb1-33dbaae59057", "type": "concept", "title": "Carrying cost and service-level performance"}, {"id": "38633fd0-908d-41b2-9668-baf651c7b6fe", "type": "concept", "title": "Segmented KPI review"}], "description": "This subtopic translates inventory performance into measures managers can act on."}, {"id": "43955e03-681c-4762-b9e0-6e09a85bc0c6", "type": "subtopic", "title": "Warehouse KPIs", "children": [{"id": "684f532f-3491-4240-ae95-77d65a301f92", "type": "concept", "title": "Dock-to-stock time"}, {"id": "cd30a6b0-816e-4f1f-a6fd-d8cea5defe2d", "type": "concept", "title": "Order cycle time"}, {"id": "fc29bb0b-85ba-470b-96c8-9dd4ce45e898", "type": "concept", "title": "Pick rate and pick accuracy"}, {"id": "16433625-cbaa-49de-af0d-4b9d5d9d51c9", "type": "concept", "title": "Cost per order, on-time shipment, and damage rate"}], "description": "Students learn to measure warehouse productivity, quality, cost, and service."}, {"id": "3ce44bd0-11f6-4735-948a-d52e66b3eee2", "type": "subtopic", "title": "Analytics and scenario modeling", "children": [{"id": "23e88371-8d7f-4d8e-b268-f858fecbf551", "type": "concept", "title": "What-if analysis"}, {"id": "b34e8e9b-34a7-4e6f-8618-88bc5a3bc8c4", "type": "concept", "title": "Simulation of labor or storage constraints"}, {"id": "a567bcd8-4497-4eb2-a453-327a38921f28", "type": "concept", "title": "Dashboard design"}, {"id": "dddb4e07-84b2-46b0-a0ee-5217540f0ba4", "type": "concept", "title": "Exception-based management"}], "description": "Students use models to test policy and layout choices before changing operations."}]}, {"id": "41da03ea-aa99-41b1-ba41-d0da78c8ca70", "type": "topic", "title": "Risk, Resilience, Sustainability, Compliance, and Ethical Operations", "description": "Plan for disruption, sustainability, traceability, labor standards, and regulatory needs.", "children": [{"id": "8043061f-322e-4efc-9ab7-0ed127f5f9b8", "type": "subtopic", "title": "Operational risk and resilience", "children": [{"id": "efc5e467-1a51-4507-93dd-6c288ab20b18", "type": "concept", "title": "Supplier and transportation disruptions"}, {"id": "d9df9482-90da-4773-aac2-c1eecf01bacd", "type": "concept", "title": "Emergency stock and strategic buffers"}, {"id": "7d331189-57bb-4ab5-83a4-b492ef29962a", "type": "concept", "title": "Business continuity plans"}, {"id": "f30fc80f-0c42-4dc5-a71a-e78f1aecc862", "type": "concept", "title": "Fire, flood, cyber, and labor disruption scenarios"}], "description": "Inventory and warehouses protect the business during disruptions. Students learn continuity thinking."}, {"id": "f9e98a2a-7f61-4d9f-9cc1-072b204defcc", "type": "subtopic", "title": "Sustainable warehousing and inventory", "children": [{"id": "033025fd-c0dc-4df8-bb25-c477378463ec", "type": "concept", "title": "Energy use and building design"}, {"id": "b8111d82-bf8f-47e4-ad42-d53d824ccfa3", "type": "concept", "title": "Packaging reduction"}, {"id": "a7130744-5bfd-4e08-9e7f-be10ca1b35fe", "type": "concept", "title": "Waste and returns disposition"}, {"id": "1553f7f1-bfe9-463b-843f-873f92103313", "type": "concept", "title": "Carbon and circularity metrics"}], "description": "Sustainability is tied to packaging, energy, waste, transport, and obsolete stock."}, {"id": "819f35fb-e2a7-46d8-ae6e-1c3c19112690", "type": "subtopic", "title": "Compliance and ethical operations", "children": [{"id": "2dc256db-9007-46f3-8d29-9b7656a1f98d", "type": "concept", "title": "Labor standards and worker safety"}, {"id": "89ace1a4-3384-4789-82f6-edbb2a904256", "type": "concept", "title": "Traceability and due diligence"}, {"id": "746b7287-e7bb-4b2f-92d8-907e977d1020", "type": "concept", "title": "Hazmat and regulated goods"}, {"id": "504b0d58-0cf2-467e-a7c0-e961802d9069", "type": "concept", "title": "Data privacy and system access controls"}], "description": "Students learn the governance responsibilities in physical operations."}]}, {"id": "211336d0-03bd-4246-91a6-69d2abb0867b", "type": "topic", "title": "Inventory and Warehouse Management Capstone", "description": "Build an integrated inventory and warehouse improvement plan using policy, layout, technology, metrics, and risk controls.", "children": [{"id": "44715aeb-3528-41da-94ec-09070b935b64", "type": "subtopic", "title": "Current-state diagnosis", "children": [{"id": "4d640001-2efd-4fb2-9fe5-142b24576f72", "type": "concept", "title": "Item and order profiles"}, {"id": "68398f24-1d53-46a0-a8bb-c807cad2ad7b", "type": "concept", "title": "Process map and layout review"}, {"id": "61ed122e-3257-4b63-94ff-89cf8d823e94", "type": "concept", "title": "KPI baseline"}, {"id": "ce7dcc1f-c613-44de-9837-6ef9338784bf", "type": "concept", "title": "Pain points and root causes"}], "description": "The capstone begins with mapping the actual inventory and warehouse problem."}, {"id": "0fe24b15-407f-4262-81b9-fb8815213e58", "type": "subtopic", "title": "Future-state design", "children": [{"id": "063df351-68fe-4e12-9303-ddfc24cecdf9", "type": "concept", "title": "Inventory policy matrix"}, {"id": "a3592bc6-6d2a-4ca3-80c1-328b65f6283f", "type": "concept", "title": "Slotting and layout changes"}, {"id": "b099aeb2-123a-4152-8af9-1c5aaa162120", "type": "concept", "title": "WMS or automation recommendations"}, {"id": "d80f5341-7213-47b9-9a63-16c878925a52", "type": "concept", "title": "Labor, safety, and training plan"}], "description": "Students create a practical improvement plan across policy, layout, people, and systems."}, {"id": "eab6d826-e7ed-4d07-8401-73b8d6d6bb43", "type": "subtopic", "title": "Implementation and business case", "children": [{"id": "7c24d573-e414-4fd7-b5e0-a43c566dd263", "type": "concept", "title": "Cost-benefit and ROI"}, {"id": "68ede6bf-7c52-44b7-a9f6-0ec97d71575d", "type": "concept", "title": "Risk and change-management plan"}, {"id": "0e1a6eb0-9f0f-42cd-becd-2abe28286459", "type": "concept", "title": "Dashboard and governance cadence"}, {"id": "a0ee1e96-df17-4160-ad1f-8fc310e4e4f1", "type": "concept", "title": "Executive presentation"}], "description": "The final step makes the plan decision-ready."}]}], "dbBacked": true}$iwmjson$::jsonb,
