update public.learning_paths
set
  title = 'Inventory and Warehouse Management',
  goal = 'Inventory and Warehouse Management',
  summary = 'The syllabus provides a comprehensive core for inventory and warehouse management. This includes demand inputs, slotting, inbound/outbound process control, safety, labor, WMS/ERP integration, automation, analytics, resilience, sustainability, and a capstone improvement plan.',
