onstraints modify textbook models."}]}, {"id": "825fe751-3630-4504-a42d-64da54c6c578", "type": "topic", "title": "Safety Stock, Service Levels, and Uncertainty", "description": "Design buffers for demand and lead-time variability while balancing cost and service.", "children": [{"id": "54e0aa8e-c857-46da-93c8-8107d38f86b6", "type": "subtopic", "title": "Uncertainty and buffers", "children": [{"id": "a8aeacbb-299a-4904-a47f-d6bba77eb0a3", "type": "concept", "title": "Demand variability"}, {"id": "eeb62aee-b6fd-4633-8711-907fcf54354f", "type": "concept", "title": "Lead-time variability"}, {"id": "b097f42a-4a7f-4f8a-9849-7b9a9aee99d4", "type": "concept", "title": "Supply disruptions"}, {"id": "8fd6e764-dd06-4677-86cd-15024bdd7b7b", "type": "concept", "title": "Service-critical items"}], "description": "Safety stock protects service when forecasts or lead times are wrong. Students learn what uncertainty is being buffered and why."}, {"id": "37a8eed8-8a63-4b15-b46b-d3262fa87e7e", "type": "subtopic", "title": "Service-level design", "children": [{"id": "92fc12e1-24e1-4fd7-a906-91df293e2dc8", "type": "concept", "title": "Cycle service level"}, {"id": "4c734a2b-a8cc-4c99-8741-d5570ab1c6de", "type": "concept", "title": "Fill rate"}, {"id": "a7ad00cf-80d9-4afa-bdf0-7d54e046ae14", "type": "concept", "title": "Stockout probability"}, {"id": "74378f4e-ae2f-4394-9e9d-1c207b2f06db", "type": "concept", "title": "Criticality-based service targets"}], "description": "This subtopic introduces the difference between service goals and inventory investment."}, {"id": "35591e37-96a2-47fb-9fb7-a92749088b97", "type": "subtopic", "title": "Pooling and risk reduction", "children": [{"id": "40ddb66a-dadc-4d8e-97c2-3dc06ccbf957", "type": "concept", "title": "Inventory pooling"}, {"id": "8a660a4a-4c06-4e1d-b69f-420346c01b8f", "type": "concept", "title": "Postponement"}, {"id": "fec23a0a-ed91-499a-8a44-9fcf33b14232", "type": "concept", "title": "Supplier reliability improvement"}, {"id": "e6fec55